const stages=[
{meta:'01 / AUTOMATED TEST REPORT',title:'A boundary bug, stated precisely.',description:'The development harness created a local case with an explicit expected result. The report was clearly labeled as automated, with no authenticated human origin.',code:'CASE live-dev-001\nObserved: exactly $100 → $5 shipping\nExpected: $100 or more → free shipping\nOrigin: automated local development test',note:'An automated report is not human approval.'},
{meta:'02 / TRIAGER AGENT',title:'Reproduce before proposing.',description:'The actual triager ran the protected checkout contract from the runtime project and handed the observed failure to the engineer in the Switch room.',code:'$ python3 -m patchroom reproduce live-dev-001\n\ntest_decimal_input ... FAIL\ntest_exact_threshold ... FAIL\nRan 6 tests · 2 assertion failures\nState: reproduced',note:'Environment errors, missing tests and timeouts do not count as reproduction.'},
{meta:'03 / ENGINEER AGENT',title:'One line. A clear explanation.',description:'The actual engineer inspected the failing evidence and authored a separate candidate. The strict comparison excluded equality at the free-shipping threshold.',code:'--- a/checkout.py\n+++ b/checkout.py\n\n- amount > Decimal("100.00")\n+ amount >= Decimal("100.00")\n\nChanged file: checkout.py',note:'The baseline and protected test contract were preserved.'},
{meta:'04 / VERIFIER AGENT',title:'Check the patch independently.',description:'The verifier re-ran both copies against the same saved contract. The baseline still failed; the candidate passed every configured check.',code:'Baseline recheck: 6 tests / 2 failures / exit 1\nCandidate:       6 tests / 0 failures / exit 0\nErrors: 0        Skips: 0\n\nProposal: p001\nState: awaiting_human_review',note:'Passing tests establish configured fixture behavior, not production correctness.'},
{meta:'05 / REVIEW BOUNDARY',title:'A person makes the decision.',description:'The workflow stops for review. This case has no authenticated human reporter, and the installed server omits required sender-type metadata. No acceptance was recorded.',code:'State: awaiting_human_review\nDecision: null\n\nCurrent candidate is preserved for inspection.\nNo merge. No deployment. No invented approval.',note:'Future authenticated decisions must match the reporter, proposal ID and full source hash.'}
];
let current=0,timer=null;const tabs=[...document.querySelectorAll('[data-step]')];
function show(index){current=Math.max(0,Math.min(stages.length-1,index));const s=stages[current];document.getElementById('stage-meta').textContent=s.meta;document.getElementById('stage-title').textContent=s.title;document.getElementById('stage-description').textContent=s.description;document.getElementById('stage-code').textContent=s.code;document.getElementById('stage-note').textContent=s.note;tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===current));tab.tabIndex=i===current?0:-1;});document.getElementById('stage-panel').setAttribute('aria-labelledby','tab-'+current);document.getElementById('previous').disabled=current===0;document.getElementById('next').disabled=current===stages.length-1;document.getElementById('progress-fill').style.width=((current+1)/stages.length*100)+'%';}
function stop(){if(timer)clearInterval(timer);timer=null;document.getElementById('play').textContent='▶ Autoplay';}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>{stop();show(i);});tab.addEventListener('keydown',e=>{if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();stop();const next=e.key==='Home'?0:e.key==='End'?4:(current+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+5)%5;show(next);tabs[next].focus();}});});
document.getElementById('previous').addEventListener('click',()=>{stop();show(current-1);});document.getElementById('next').addEventListener('click',()=>{stop();show(current+1);});document.getElementById('play').addEventListener('click',()=>{if(timer){stop();return;}if(current===4)show(0);document.getElementById('play').textContent='Ⅱ Pause';timer=setInterval(()=>{show(current+1);if(current===4)stop();},5500);});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});show(0);
